function validate([cost]) {
  if (!Array.isArray(cost) || cost.length < 1 || cost.length > 100) return 'cost needs 1 to 100 prices.';
  if (cost.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each price is a whole number from 1 to 100.';
  return null;
}

