function minimumCost(cost) {
  // Memoised search over the set of candies still to collect.
  const n = cost.length;
  const memo = new Map();
  const solve = (mask) => {
    if (mask === 0) return 0;
    if (memo.has(mask)) return memo.get(mask);
    const left = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) left.push(i);
    let best = Infinity;
    for (const i of left) best = Math.min(best, cost[i] + solve(mask & ~(1 << i)));
    for (let a = 0; a < left.length; a++)
      for (let b = a + 1; b < left.length; b++) {
        const i = left[a], j = left[b];
        const paid = cost[i] + cost[j];
        const rest = mask & ~(1 << i) & ~(1 << j);
        best = Math.min(best, paid + solve(rest));
        for (const k of left)
          if (k !== i && k !== j && cost[k] <= Math.min(cost[i], cost[j]))
            best = Math.min(best, paid + solve(rest & ~(1 << k)));
      }
    memo.set(mask, best);
    return best;
  };
  return solve((1 << n) - 1);
}

